package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type PartRec struct {
	LbPart   string
	LbRegion string
	LbSerial int64
}

var WsEofFlag string = "N"
var WsLabel string = strings.Repeat(" ", 20)
var WsACount int64 = 0
var WsTotalA int64 = 0
var WsCount int64 = 0

var PartRecInst PartRec

var partFileReader *bufio.Reader
var partFileHandle *os.File
var InputDone bool = false

func formatNumeric(value int64, digits int) string {
	s := fmt.Sprintf("%d", value)
	negative := false
	if len(s) > 0 && s[0] == '-' {
		negative = true
		s = s[1:]
	}
	// Keep only low-order digits that fit
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	s = strings.Repeat("0", digits-len(s)) + s
	if negative {
		// COBOL would handle sign; not needed here (counts are non-negative)
		if len(s) > 0 {
			s = "-" + s[1:]
		}
	}
	return s
}

func formatDecimal(d decimal.Decimal, digits int, scale int32) string {
	s := d.StringFixed(scale)
	_ = digits
	return s
}

func readRecord() (string, bool) {
	line, err := partFileReader.ReadString('\n')
	if err != nil {
		if len(line) == 0 {
			return "", true
		}
		// EOF with partial line: return it as last record
		line = strings.TrimRight(line, "\r\n")
		return line, false
	}
	line = strings.TrimRight(line, "\r\n")
	return line, false
}

func padRight(s string, n int) string {
	if len(s) > n {
		return s[:n]
	}
	if len(s) < n {
		return s + strings.Repeat(" ", n-len(s))
	}
	return s
}

func mainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		// If file doesn't exist, treat as empty (COBOL would error, but tests may have no file)
		// To match expected behaviour, create empty reader
		partFileHandle = nil
		partFileReader = bufio.NewReader(strings.NewReader(""))
	} else {
		partFileHandle = f
		partFileReader = bufio.NewReader(f)
	}
	if partFileHandle != nil {
		defer partFileHandle.Close()
	}
	readPara()
	for !InputDone {
		processPara()
	}
	closePartFile()
	summaryPara()
}

func closePartFile() {
	if partFileHandle != nil {
		partFileHandle.Close()
	}
}

func readPara() {
	line, eof := readRecord()
	if eof {
		WsEofFlag = "Y"
		InputDone = true
		return
	}
	// Pad with spaces to record length 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	PartRecInst.LbPart = line[0:8]
	PartRecInst.LbRegion = line[8:11]
	// LB-SERIAL PIC 9(4) digits only
	sSerial := line[11:15]
	sSerial = strings.TrimSpace(sSerial)
	if sSerial == "" {
		PartRecInst.LbSerial = 0
	} else {
		var v int64
		fmt.Sscanf(sSerial, "%d", &v)
		PartRecInst.LbSerial = v
	}
}

func processPara() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0

	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	cnt := int64(strings.Count(PartRecInst.LbPart, "A"))
	WsACount = cnt

	// STRING LB-REGION DELIMITED BY SPACE "-" DELIMITED BY SIZE LB-PART DELIMITED BY SPACE "-" DELIMITED BY SIZE LB-SERIAL DELIMITED BY SIZE INTO WS-LABEL
	// Build sources
	var parts []string

	// LB-REGION DELIMITED BY SPACE
	{
		s := PartRecInst.LbRegion
		if idx := strings.Index(s, " "); idx >= 0 {
			s = s[:idx]
		}
		parts = append(parts, s)
	}
	// "-" DELIMITED BY SIZE
	parts = append(parts, "-")
	// LB-PART DELIMITED BY SPACE
	{
		s := PartRecInst.LbPart
		if idx := strings.Index(s, " "); idx >= 0 {
			s = s[:idx]
		}
		parts = append(parts, s)
	}
	// "-" DELIMITED BY SIZE
	parts = append(parts, "-")
	// LB-SERIAL DELIMITED BY SIZE : need 4-digit zero-padded representation as stored? PIC 9(4) display as digits.
	{
		s := formatNumeric(PartRecInst.LbSerial, 4)
		parts = append(parts, s)
	}

	// Concatenate into WS-LABEL of size 20, not clearing beyond used? But we already blanked.
	// STRING does not clear target, but we blanked first.
	// Concatenate and pad with spaces if not filled (already spaces)
	concatenated := strings.Join(parts, "")
	if len(concatenated) > 20 {
		concatenated = concatenated[:20]
	}
	// Place into WS-LABEL, preserving trailing spaces
	WsLabel = padRight(concatenated, 20)

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	WsTotalA = WsTotalA + WsACount
	WsCount = WsCount + 1

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is PIC X(20) -> exactly 20 chars
	// WS-A-COUNT is PIC 99 zero-padded 2 digits
	fmt.Printf("%s A=%s\n", WsLabel, formatNumeric(WsACount, 2))

	readPara()
}

func summaryPara() {
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", formatNumeric(WsCount, 3), formatNumeric(WsTotalA, 3))
}

func main() {
	mainPara()
}
